<?php require __DIR__.'/includes/bootstrap.php';if(!empty($_SESSION['user_id']))redirect($_SESSION['role']==='admin'?'/admin':'/dashboard');$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);$l=trim($_POST['login']??'');$p=$_POST['password']??'';$q=$db->prepare('SELECT * FROM users WHERE username=? OR email=? LIMIT 1');$q->execute([$l,$l]);$u=$q->fetch();if($u&&$u['status']==='active'&&password_verify($p,$u['password_hash'])){login_user($u);redirect($u['role']==='admin'?'/admin':'/dashboard');}$error='Invalid credentials.';}$title='Login';require __DIR__.'/includes/header.php';?><div class="card" style="max-width:460px;margin:70px auto"><h1 style="font-size:38px">Login</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form class="form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Username or Email<input class="input" name="login" required></label><label>Password<input class="input" type="password" name="password" required></label><button class="btn">Login</button></form></div><?php require __DIR__.'/includes/footer.php';?>